package br.com.sideral.service;
import java.util.HashMap; import java.util.List; import java.util.Map; import br.com.sideral.domain.ControlItem; import br.com.sideral.domain.TrafficColor; import br.com.sideral.repository.ControlItemRepository; import br.com.sideral.repository.DeploymentRepository; import br.com.sideral.repository.DriverTrainingRepository; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DashboardService {
 @Autowired private ControlItemRepository controlItems; @Autowired private DeploymentRepository deployments; @Autowired private DriverTrainingRepository trainings;
 @Transactional(readOnly=true) public Map<String,Object> indicators(){Map<String,Object> map=new HashMap<String,Object>();List<ControlItem> all=controlItems.findAll();map.put("items",all);map.put("total",Integer.valueOf(all.size()));map.put("green",Integer.valueOf(controlItems.findByColor(TrafficColor.GREEN).size()));map.put("yellow",Integer.valueOf(controlItems.findByColor(TrafficColor.YELLOW).size()));map.put("red",Integer.valueOf(controlItems.findByColor(TrafficColor.RED).size()));map.put("openActions",Integer.valueOf(deployments.findOpen().size()));map.put("expiredTraining",Integer.valueOf(trainings.findExpired().size()));return map;}
}